import { AsyncLocalStorage } from 'node:async_hooks';
const store = new AsyncLocalStorage();

http.createServer((req, res) => {
  const ctx = { requestId: crypto.randomUUID(), tenant: tenantFrom(req) };
  store.run(ctx, async () => {        // bind for the whole request
    await handle(req, res);            // no ctx parameter anywhere below
  });
}).listen(8080);

function currentRequestId() { return store.getStore()?.requestId; }
